class Solution {
public:
    long long kSum(std::vector<int>& nums, int k) {
        long long max_sum = 0;
        std::vector<long long> abs_vals;
        abs_vals.reserve(nums.size());
        for (int x : nums) {
            if (x > 0) max_sum += x;
            abs_vals.push_back(std::abs((long long)x));
        }
        std::sort(abs_vals.begin(), abs_vals.end());
        if (k == 1) return max_sum;

        using P = std::pair<long long, int>;
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        pq.push({abs_vals[0], 0});

        long long sub = 0;
        for (int step = 0; step < k - 1; step++) {
            auto [val, i] = pq.top();
            pq.pop();
            sub = val;
            if (i + 1 < (int)abs_vals.size()) {
                pq.push({val + abs_vals[i + 1], i + 1});
                pq.push({val - abs_vals[i] + abs_vals[i + 1], i + 1});
            }
        }
        return max_sum - sub;
    }
};

class Solution {
    public long kSum(int[] nums, int k) {
        long maxSum = 0;
        long[] absVals = new long[nums.length];
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > 0) maxSum += nums[i];
            absVals[i] = Math.abs((long) nums[i]);
        }
        java.util.Arrays.sort(absVals);
        if (k == 1) return maxSum;

        java.util.PriorityQueue<long[]> pq = new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{absVals[0], 0});

        long sub = 0;
        for (int step = 0; step < k - 1; step++) {
            long[] top = pq.poll();
            long val = top[0];
            int i = (int) top[1];
            sub = val;
            if (i + 1 < absVals.length) {
                pq.offer(new long[]{val + absVals[i + 1], i + 1});
                pq.offer(new long[]{val - absVals[i] + absVals[i + 1], i + 1});
            }
        }
        return maxSum - sub;
    }
}

var kSum = function(nums, k) {
    let maxSum = 0n;
    const absVals = [];
    for (const x of nums) {
        if (x > 0) maxSum += BigInt(x);
        absVals.push(BigInt(Math.abs(x)));
    }
    absVals.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    if (k === 1) return Number(maxSum);

    class MinHeap {
        constructor() { this.data = []; }
        push(val) {
            this.data.push(val);
            let i = this.data.length - 1;
            while (i > 0) {
                let p = (i - 1) >> 1;
                if (this.data[p][0] <= this.data[i][0]) break;
                [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
                i = p;
            }
        }
        pop() {
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                let i = 0;
                while ((i << 1) + 1 < this.data.length) {
                    let l = (i << 1) + 1, r = l + 1, smallest = i;
                    if (this.data[l][0] < this.data[smallest][0]) smallest = l;
                    if (r < this.data.length && this.data[r][0] < this.data[smallest][0]) smallest = r;
                    if (smallest === i) break;
                    [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                    i = smallest;
                }
            }
            return top;
        }
    }

    const pq = new MinHeap();
    pq.push([absVals[0], 0]);
    let sub = 0n;
    for (let step = 0; step < k - 1; step++) {
        const [val, i] = pq.pop();
        sub = val;
        if (i + 1 < absVals.length) {
            pq.push([val + absVals[i + 1], i + 1]);
            pq.push([val - absVals[i] + absVals[i + 1], i + 1]);
        }
    }
    return Number(maxSum - sub);
};
